using namespace std;
typedef long long ll;
const int MOD=1e9+7;
const int MAXN=1e5+5;
int n,k;
ll ans[MAXN],sum;
ll qpow(int a, int b) {
	ll ans = 1, base = a;
	while (b) {
		if (b & 1) ans = ans * base % MOD;
		b >>= 1, base = base * base % MOD;
	}
	return ans;
}
int main() {
	cin>>n>>k;
	for(int x=k; x; x--) {
		ans[x]=qpow(k/x,n);
