bool cmp(const Robot &x,const Robot &y){return x.x<y.x;}
struct Fenwick_Tree{
	int c[N];
	int lowbit(int x){return x & (-x);}
	void add(int x,int y){for(;x<=n;x+=lowbit(x))c[x]=max(c[x],y);}
	int ask(int x){int r=0;for(;x;x-=lowbit(x))r=max(r,c[x]);return r;}
}tr;
